func (s *Service) pollProjectPullRequests(ctx context.Context, db *store.DB, project store.Project, cfg config.Config, force bool) error {
	return s.pollProjectPullRequestsWithMergedCallback(ctx, db, project, cfg, force, nil)
}

func (s *Service) pollProjectPullRequestsWithMergedCallback(ctx context.Context, db *store.DB, project store.Project, cfg config.Config, force bool, onWorkspaceTaskMerged func()) error {
	if project.IsWorkspace() {
		return s.pollWorkspacePullRequestsAndNotify(ctx, db, project, cfg, force, onWorkspaceTaskMerged)
	}
	targetMoved := false
	if err := s.pollProjectPullRequestsPass(ctx, db, project, cfg, force, &targetMoved, nil); err != nil || !targetMoved {
		return err
	}
	// An open PR whose target advanced during the forge query may have merged
	// or fallen behind. Query again now rather than at the next poll.
	return s.pollProjectPullRequestsPass(ctx, db, project, cfg, true, nil, nil)
}

var (
	prPollContendedRetry    = 50 * time.Millisecond
	errProjectPollClaimHeld = errors.New("project poll claim remained held")
)

// refreshProjectPullRequests is a forced poll whose result a caller guards
// on. While another poller, such as the Project watch, holds the poll claim,
// its observations may predate this call, so the refresh waits for that poll
// to finish and polls again until ctx ends.
func (s *Service) refreshProjectPullRequests(ctx context.Context, db *store.DB, project store.Project, cfg config.Config) error {
	if project.IsWorkspace() {
		return s.pollProjectPullRequests(ctx, db, project, cfg, true)
	}
	for {
		targetMoved, contended := false, false
		if err := s.pollProjectPullRequestsPass(ctx, db, project, cfg, true, &targetMoved, &contended); err != nil {
			return err
		}
		if targetMoved {
			return s.pollProjectPullRequestsPass(ctx, db, project, cfg, true, nil, nil)
		}
		if !contended {
			return nil
		}
		select {
		case <-ctx.Done():
			return fmt.Errorf("%w: %w", errProjectPollClaimHeld, ctx.Err())
		case <-time.After(prPollContendedRetry):
		}
	}
}

// pollProjectPullRequestsPass observes every watched PR once. It sets
// targetMoved when an open PR's target advanced during the forge query, and
// contended when another poller held the claim so nothing was observed.
func (s *Service) pollProjectPullRequestsPass(ctx context.Context, db *store.DB, project store.Project, cfg config.Config, force bool, targetMoved, contended *bool) error {
	now := time.Now()
	interval := parseDurationOr(cfg.Defaults.PRPoll, 2*time.Minute)
	claim, err := db.ClaimPRPoll(ctx, project.ID, now, interval, force)
	if err != nil {
		return err
	}
	if claim == "" {
		if contended != nil {
			*contended = true
		}
		return nil
	}
	defer releaseProjectPRPollWithRetry(db, project.ID, claim)
	if err := s.processPendingStackedTargetChanges(ctx, db, project, cfg, ""); err != nil {
		return err
	}
	tasks, err := db.Tasks(ctx, project.ID, false)
	if err != nil {
		return err
	}
	watched := make([]store.Task, 0)
	for _, task := range tasks {
		if task.PRURL == "" {
			continue
		}
		previous, previousErr := db.LatestPRObservation(ctx, task.ID)
		if previousErr != nil && !store.IsNotFound(previousErr) {
			return previousErr
		}
		if previousErr == nil && previous.PRURL == task.PRURL && previous.State == "CLOSED" {
			if err := raiseClosedPRDecision(ctx, db, project, task, task.PRURL); err != nil {
				return err
			}
		}
		watched = append(watched, task)
	}
	if len(watched) == 0 {
		if err := s.retrySpecReadyChecks(ctx, db, project, cfg, now); err != nil {
			return err
		}
		return db.RecordPRPollAttempt(ctx, project.ID, now.UnixMilli())
	}
	targets := make([]prWatchTarget, 0, len(watched))
	failedTasks := make(map[int64]error)
	staleBeforeQuery := make(map[int64]bool)
	// One tip per target branch, fetched before the forge query. An OPEN
	// observation is behind only if it lacks this tip: a tip fetched after
	// the query may already contain this PR's own merge.
	targetTips := make(map[string]prTargetFreshness)
	for _, task := range watched {
		var targetTip prTargetFreshness
		if cfg.Defaults.RequireCurrentTarget {
			branch := taskTargetBranch(project, task)
			fetched := false
			if targetTip, fetched = targetTips[branch]; !fetched {
				var fetchErr error
				if targetTip, fetchErr = fetchPRTargetTip(ctx, project.Root, branch); fetchErr != nil {
					failedTasks[task.ID] = fetchErr
					staleBeforeQuery[task.ID] = true
					continue
				}
				targetTips[branch] = targetTip
			}
		}
		headSHA := task.GatedSHA
		if headSHA == "" && task.WorktreePath != "" && task.Branch != "" {
			headSHA, _ = gitOutput(ctx, task.WorktreePath, "rev-parse", "refs/heads/"+task.Branch)
		}
		if headSHA == "" {
			previous, previousErr := db.LatestPRObservation(ctx, task.ID)
			if previousErr == nil && previous.PRURL == task.PRURL {
				headSHA = previous.HeadSHA
			}
		}
		if headSHA == "" {
			staleBeforeQuery[task.ID] = true
			continue
		}
		if !cfg.Defaults.RequireCurrentTarget {
			continue
		}
		freshness, freshnessErr := targetTip.of(ctx, project.Root, headSHA)
		if freshnessErr != nil {
			failedTasks[task.ID] = freshnessErr
			staleBeforeQuery[task.ID] = true
			continue
		}
		if !freshness.Fresh {
			// The target may have advanced because this PR just merged. Defer
			// queuing a sync instruction until GraphQL confirms the PR is open.
			staleBeforeQuery[task.ID] = true
		}
	}
	forge, forgeErr := forgeForRepository(ctx, project.Root, cfg, "")
	globalFailure := ""
	if forgeErr != nil {
		globalFailure = truncate(forgeErr.Error(), 300)
	}
	gitlabTargets := make([]store.Task, 0)
	for _, task := range watched {
		if forgeErr != nil {
			continue
		}
		_, refErr := forgeReference(task.PRURL, forge)
		if refErr != nil {
			failedTasks[task.ID] = refErr
			continue
		}
		if forge.Kind == "gitlab" {
			gitlabTargets = append(gitlabTargets, task)
		} else {
			targets = append(targets, prWatchTarget{Task: task, Pull: "pr" + strconv.Itoa(task.Seq), SkipChecks: staleBeforeQuery[task.ID]})
		}
	}
	query, targets := pullRequestGraphQLQuery(targets)
	pulls := make(map[int64]*ghPullRequest, len(targets))
	var response ghQueryResponse
	forgeAnswered := false
	if query != "" {
		output, stderr, commandErr := graphQLCommandOutput(ctx, project.Root, query)
		if err := json.Unmarshal([]byte(output), &response); err != nil {
			failure := "invalid GraphQL response: " + err.Error()
			if commandErr != nil {
				failure = truncate(strings.TrimSpace(stderr+" "+commandErr.Error()), 300)
			}
			if _, recordErr := db.RecordPRPoll(ctx, project.ID, now.UnixMilli(), failure); recordErr != nil {
				return recordErr
			}
			return nil
		}
		if commandErr != nil && (len(response.Errors) == 0 || errors.Is(commandErr, context.Canceled) || errors.Is(commandErr, context.DeadlineExceeded)) {
			globalFailure = truncate(strings.TrimSpace(stderr+" "+commandErr.Error()), 300)
		}
		hasRepositoryData := len(response.Data.Repositories) > 0
		forgeAnswered = hasRepositoryData
		if !hasRepositoryData {
			globalFailure = truncate(strings.TrimSpace(globalFailure+" GraphQL response omitted repository data"), 300)
		}
		for _, failure := range response.Errors {
			attributed := false
			if hasRepositoryData && len(failure.Path) > 0 {
				repository, _ := failure.Path[0].(string)
				pull := ""
				if len(failure.Path) > 1 {
					pull, _ = failure.Path[1].(string)
				}
				for _, target := range targets {
					if target.Repository == repository && (pull == "" || target.Pull == pull) {
						failedTasks[target.Task.ID] = errors.New(failure.Message)
						attributed = true
					}
				}
			}
			if !attributed {
				globalFailure = truncate(strings.TrimSpace(globalFailure+" "+failure.Message), 300)
			}
		}
		if hasRepositoryData {
			for _, target := range targets {
				if failedTasks[target.Task.ID] != nil {
					continue
				}
				repositoryData, repositoryExists := response.Data.Repositories[target.Repository]
				if !repositoryExists || len(repositoryData) == 0 || string(repositoryData) == "null" {
					globalFailure = truncate(strings.TrimSpace(globalFailure+" GraphQL response omitted repository alias "+target.Repository), 300)
					continue
				}
				pull, pullErr := response.pullRequest(target)
				if pullErr != nil {
					failedTasks[target.Task.ID] = pullErr
					continue
				}
				pulls[target.Task.ID] = pull
			}
		}
	}
	gitlabObservations := make(map[int64]store.PRObservation)
	gitlabFailures := make(map[int64][]failedCheck)
	for _, task := range gitlabTargets {
		observation, failures, pollErr := gitlabObservationWithChecks(ctx, forge, task, taskTargetBranch(project, task), now.UnixMilli(), !staleBeforeQuery[task.ID])
		if pollErr != nil {
			failedTasks[task.ID] = pollErr
			continue
		}
		gitlabObservations[task.ID] = observation
		gitlabFailures[task.ID] = failures
		forgeAnswered = true
	}
	if globalFailure != "" {
		if _, err := db.RecordPRPoll(ctx, project.ID, now.UnixMilli(), globalFailure); err != nil {
			return err
		}
	} else if len(failedTasks) > 0 && !forgeAnswered {
		if err := db.RecordPRPollAttempt(ctx, project.ID, now.UnixMilli()); err != nil {
			return err
		}
	} else if _, err := db.RecordPRPoll(ctx, project.ID, now.UnixMilli(), ""); err != nil {
		return err
	}
	if forgeErr == nil && forge.Kind != "gitlab" {
		s.recordTargetBranchCIFailures(ctx, db, project, forge, watched, now)
	}
	type pendingObservation struct {
		task       store.Task
		current    store.PRObservation
		failures   []failedCheck
		ciFailures []failedCheck
		previous   store.PRObservation
		hasBefore  bool
	}
	observations := make([]pendingObservation, 0, len(targets))
	type behindPR struct {
		task      store.Task
		freshness prTargetFreshness
		headSHA   string
	}
	behind := []behindPR{}
	moved := false
	// Without the current-target rule, conflicting non-full-pipeline PRs bypass
	// the queue; stale full-pipeline candidates use it to serialize refreshes.
	conflicts := []behindPR{}
	for _, task := range watched {
		if taskErr := failedTasks[task.ID]; taskErr != nil {
			if strings.Contains(taskErr.Error(), "Could not resolve to a PullRequest") {
				if err := raiseInvalidPRDecision(ctx, db, project, task); err != nil {
					return err
				}
				continue
			}
			if err := recordPRTaskWatchFailure(ctx, db, project, task, taskErr, now); err != nil {
				return err
			}
			continue
		}
		pull := pulls[task.ID]
		if pull == nil && forge.Kind != "gitlab" {
			continue
		}
		previous, previousErr := db.LatestPRObservation(ctx, task.ID)
		hasPrevious := previousErr == nil && previous.PRURL == task.PRURL
		if previousErr != nil && !store.IsNotFound(previousErr) {
			return previousErr
		}
		var observation store.PRObservation
		var failures []failedCheck
		if forge.Kind == "gitlab" {
			observation, failures = gitlabObservations[task.ID], gitlabFailures[task.ID]
		} else {
			if strings.EqualFold(pull.Mergeable, "UNKNOWN") && hasPrevious {
				pull.Mergeable = previous.Mergeable
			}
			observation, failures, err = makePRObservation(project.ID, task, pull, now, taskTargetBranch(project, task))
			if strings.EqualFold(pull.MergeStateStatus, "BEHIND") {
				observation.Mergeable = "BEHIND"
			}
		}
		if observation.Mergeable == "UNKNOWN" && hasPrevious {
			observation.Mergeable = previous.Mergeable
		}
		if err != nil {
			if recordErr := recordPRTaskWatchFailure(ctx, db, project, task, err, now); recordErr != nil {
				return recordErr
			}
			continue
		}
		retainGreenObservation := false
		if observation.State == "OPEN" && (cfg.Defaults.RequireCurrentTarget || observation.Mergeable == "CONFLICTING" || observation.Mergeable == "BEHIND" || fullPipelineSelected(task, "")) {
			freshness, freshnessErr := inspectPRTargetFreshness(ctx, project.Root, taskTargetBranch(project, task), observation.HeadSHA)
			var beforeQuery prTargetFreshness
			if freshnessErr == nil && !freshness.Fresh && cfg.Defaults.RequireCurrentTarget {
				beforeQuery, freshnessErr = targetTips[freshness.Branch].of(ctx, project.Root, observation.HeadSHA)
			}
			if freshnessErr != nil {
				if recordErr := recordPRTaskWatchFailure(ctx, db, project, task, freshnessErr, now); recordErr != nil {
					return recordErr
				}
				continue
			}
			if !freshness.Fresh && !cfg.Defaults.RequireCurrentTarget && (observation.Mergeable == "CONFLICTING" || observation.Mergeable == "BEHIND") && !fullPipelineSelected(task, "") {
				conflicts = append(conflicts, behindPR{task: task, freshness: freshness, headSHA: observation.HeadSHA})
			} else if !freshness.Fresh {
				// A target that advanced only during the query may hold this
				// PR's own merge; a later query observes it merged or behind.
				if beforeQuery.Fresh {
					moved = true
				} else {
					// Enter every behind Task before promoting, so the head follows
					// done Signal order rather than poll order.
					if err := db.EnterMergeQueue(ctx, task.ID, "", freshness.Branch, now.UnixMilli()); err != nil {
						return err
					}
					behind = append(behind, behindPR{task: task, freshness: freshness, headSHA: observation.HeadSHA})
					if fullPipelineSelected(task, "") && hasPrevious && previous.HeadSHA == observation.HeadSHA {
						place, placeErr := db.PlaceInMergeQueue(ctx, task.ID, "", freshness.Branch, now.UnixMilli())
						if placeErr != nil {
							return placeErr
						}
						if !place.Head() {
							observation.Checks = previous.Checks
							failures = nil
							retainGreenObservation = true
						}
					}
				}
				if !retainGreenObservation {
					observation.Checks = stalePRChecks()
					failures = nil
				}
			}
		}
		if observation.State == "MERGED" {
			if err := db.DequeueMergeQueue(ctx, task.ID, "", "merged", now.UnixMilli()); err != nil {
				return err
			}
			verified, verifyErr := db.WasVerifiedPRHead(ctx, task.ID, task.PRURL, observation.HeadSHA)
			if verifyErr != nil {
				return verifyErr
			}
			// A head still on the Sandbox's Task branch is also the Worker's own.
			if !verified && task.WorktreePath != "" && task.Branch != "" {
				verified = headOnTaskBranch(ctx, task.WorktreePath, task.Branch, observation.HeadSHA)
			}
			if !verified {
				if err := raiseUngatedMergedHeadNotice(ctx, db, project, task, task.WorktreePath, "", task.PRURL, task.GatedSHA, observation.HeadSHA); err != nil {
					return err
				}
				continue
			}
			if (task.State != store.StateMerging || task.GatedSHA != observation.HeadSHA) && validateWorkerPullRequestWithRemote(ctx, project, task, forge, task.PRURL, observation.HeadSHA, false) != nil {
				err := fmt.Errorf("merged pull request identity could not be verified for %s", task.PRURL)
				if recordErr := recordPRTaskWatchFailure(ctx, db, project, task, err, now); recordErr != nil {
					return recordErr
				}
				continue
			}
		}
		ciFailures := failures
		if forge.Kind != "gitlab" && pull.checksRunning() {
			ciFailures = nil
		}
		if len(ciFailures) > 0 {
			// A red head leaves the queue so it cannot block the next entry.
			if err := db.DequeueMergeQueue(ctx, task.ID, "", "checks_failed", now.UnixMilli()); err != nil {
				return err
			}
		}
		observations = append(observations, pendingObservation{task: task, current: observation, failures: failures, ciFailures: ciFailures, previous: previous, hasBefore: hasPrevious})
	}
	if targetMoved != nil {
		*targetMoved = moved
	}
	// A pass that saw a target move cannot order its queue: a deferred PR
	// may belong ahead of the PRs it saw behind. The next pass promotes.
	if moved {
		behind = nil
	}
	for _, pending := range behind {
		if _, err := s.queuePRTargetSyncInstruction(ctx, db, pending.task, "", pending.freshness, pending.headSHA); err != nil {
			return err
		}
	}
	for _, pending := range conflicts {
		if err := s.queueConflictTargetSyncInstruction(ctx, db, pending.task, "", pending.freshness, pending.headSHA); err != nil {
			return err
		}
	}
	for _, observed := range observations {
		observed.current = preserveMergeRequest(observed.current, observed.previous, observed.hasBefore)
		effect := prObservationEffect(project, observed.task, observed.current, observed.failures, observed.previous, observed.hasBefore)
		// merge_ready tells the Lead to merge, so it waits for the review
		// gate `posse merge` applies to the same head.
		mergeReady := func(notice store.Notice) bool { return notice.Kind == "merge_ready" }
		if slices.ContainsFunc(effect.Notices, mergeReady) {
			gateErr := requireSelectedReviewAt(ctx, db, project, cfg, observed.task, observed.current.HeadSHA)
