			if err := db.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM notices WHERE task_id=? AND kind='pr_merged' AND data_json=?)`, observed.task.ID, marshalJSON(map[string]any{"url": observed.current.PRURL, "head_sha": observed.current.HeadSHA, "merge_commit": observed.current.MergeCommit})).Scan(&exists); err != nil {
				return err
			}
			if !exists {
				effect.Notices = append(effect.Notices, store.Notice{ProjectID: project.ID, TaskID: observed.task.ID, Kind: "pr_merged", Summary: observed.task.Title + ": pull request merged", DataJSON: marshalJSON(map[string]any{"url": observed.current.PRURL, "head_sha": observed.current.HeadSHA, "merge_commit": observed.current.MergeCommit}), CreatedAt: observed.current.ObservedAt})
			}
		}
		observed.current.Checks = stampNoticedFailures(observed.current, observed.previous, observed.hasBefore, observed.failures, effect)
		recorded, err := db.RecordPRObservation(ctx, observed.current, effect, observed.task)
		if err != nil {
			return err
		}
		if observed.current.State == "OPEN" {
			if err := s.processCIObservation(ctx, db, project, observed.task, observed.current, observed.ciFailures, forge, ""); err != nil {
				return err
			}
			if err := s.refreshPRValidationBlock(ctx, db, project, observed.task, forge, observed.current.PRURL, ""); err != nil {
				if noticeErr := recordPRTaskWatchFailure(ctx, db, project, observed.task, err, now); noticeErr != nil {
					return noticeErr
				}
			}
		}
		if recorded && observed.current.State == "CLOSED" {
			if err := raiseClosedPRDecision(ctx, db, project, observed.task, observed.current.PRURL); err != nil {
				return err
			}
		}
		if recorded && observed.current.State == "MERGED" {
			if _, err := s.syncTaskTarget(ctx, db, project, observed.task); err != nil {
				if noticeErr := recordPRTaskWatchFailure(ctx, db, project, observed.task, err, now); noticeErr != nil {
					return noticeErr
				}
			}
			if _, err := s.syncProjectRoot(ctx, db, project, cfg, true); err != nil {
				if noticeErr := recordPRTaskWatchFailure(ctx, db, project, observed.task, err, now); noticeErr != nil {
					return noticeErr
				}
			}
		}
	}
	if err := s.retrySpecReadyChecks(ctx, db, project, cfg, now); err != nil {
		return err
	}
	for _, observed := range observations {
		if observed.current.State != "MERGED" {
			continue
		}
		if err := s.enqueueStackedTargetChanges(ctx, db, project, observed.task, "", taskTargetBranch(project, observed.task)); err != nil {
			return err
		}
	}
	if err := s.processPendingStackedTargetChanges(ctx, db, project, cfg, ""); err != nil {
		return err
	}
	return nil
}

func (s *Service) retrySpecReadyChecks(ctx context.Context, db *store.DB, project store.Project, cfg config.Config, now time.Time) error {
	merged, err := db.TasksInState(ctx, project.ID, store.StateMerged)
	if err != nil {
		return err
	}
	var forge repositoryForge
	var forgeErr error
	resolved := false
	for _, task := range merged {
		checked, err := db.SpecReadyChecked(ctx, task.ID)
		if err != nil {
			return err
		}
		if checked || task.PRURL == "" {
			continue
		}
		if !resolved {
			forge, forgeErr = forgeForRepository(ctx, project.Root, cfg, "")
			resolved = true
		}
		err = forgeErr
		if err == nil {
			err = s.raiseSpecReadyToDeliver(ctx, db, project, task, forge)
		}
		if err != nil {
			if noticeErr := recordPRTaskWatchFailure(ctx, db, project, task, err, now); noticeErr != nil {
				return noticeErr
			}
		} else if err := db.MarkSpecReadyChecked(ctx, task.ID); err != nil {
			return err
		}
	}
	return nil
}

// reviewGateRefusal tells the gate's policy answer, such as missing evidence,
// from an operational failure to evaluate it.
func reviewGateRefusal(err error) bool {
	var failure *axi.Error
	return errors.As(err, &failure) && !failure.Retryable
}

// reviewPolicyViolation evaluates the selected evidence for the head the forge
// merged. A merge Posse did not guard still Merges (ADR 0011), but it never gains
// a fabricated pass: the missing evidence is reported as a policy violation.
func reviewPolicyViolation(ctx context.Context, db *store.DB, project store.Project, cfg config.Config, task store.Task, merged store.PRObservation) (store.Notice, bool) {
	err := requireSelectedReviewForMerge(ctx, db, project, cfg, task, merged.HeadSHA, merged.MergeCommit)
	if err == nil {
		return store.Notice{}, false
	}
	code, message := "review_evidence_unverified", err.Error()
	var failure *axi.Error
	if errors.As(err, &failure) {
		code, message = failure.Code, failure.Message
	}
	return store.Notice{
		ProjectID: project.ID, TaskID: task.ID, Kind: "review_policy_violation",
		Summary:   task.Title + ": pull request merged at " + shortSHA(merged.HeadSHA) + " without the selected review evidence: " + truncate(message, 240),
		DataJSON:  marshalJSON(map[string]any{"url": merged.PRURL, "head_sha": merged.HeadSHA, "merge_commit": merged.MergeCommit, "evidence_error": code, "detail": message}),
		CreatedAt: merged.ObservedAt,
	}, true
}

// gh may exit nonzero for a single GraphQL error while still printing usable
// data for the other aliases. Keep stderr separate so it cannot corrupt JSON.
func graphQLCommandOutput(ctx context.Context, root, query string) (string, string, error) {
	timeout := externalCommandTimeoutValue()
	commandCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	command := execgroup.CommandContext(commandCtx, externalCommandPath("gh"), "api", "graphql", "-f", "query="+query)
	command.Dir = root
	command.Env = externalCommandEnvironment("gh")
	var stdout, stderr bytes.Buffer
	command.Stdout, command.Stderr = &stdout, &stderr
	err := command.Run()
	if commandCtx.Err() != nil {
		if errors.Is(commandCtx.Err(), context.DeadlineExceeded) {
			err = fmt.Errorf("gh timed out after %s: %w", timeout, context.DeadlineExceeded)
		} else {
			err = commandCtx.Err()
		}
	}
	return stdout.String(), stderr.String(), err
}

func pullRequestGraphQLQuery(targets []prWatchTarget) (string, []prWatchTarget) {
	if len(targets) == 0 {
		return "", nil
	}
	groups := make([]string, 0)
	groupAliases := make(map[string]string)
	groupFields := make(map[string][]string)
	for index := range targets {
		ref, err := pullRequestReferenceFromURL(targets[index].Task.PRURL)
		if err != nil {
			continue
		}
		key := strings.ToLower(ref.Host + "/" + ref.Owner + "/" + ref.Repo)
		repository, found := groupAliases[key]
		if !found {
			repository = "repo" + strconv.Itoa(len(groupAliases)+1)
			groupAliases[key] = repository
			groups = append(groups, repository)
		}
		targets[index].Repository = repository
		checksField := ""
		if !targets[index].SkipChecks {
			checksField = `statusCheckRollup {
    state
    contexts(first: 100) {
      nodes {
        __typename
        ... on CheckRun { databaseId name status conclusion detailsUrl checkSuite { workflowRun { databaseId } } }
        ... on StatusContext { context state targetUrl }
      }
    }
  }`
		}
		groupFields[repository] = append(groupFields[repository], fmt.Sprintf(`%s: pullRequest(number: %d) {
  url state headRefOid baseRefName mergeable mergeStateStatus reviewDecision mergeCommit { oid }
  %s
	}`, targets[index].Pull, ref.Number, checksField))
	}
	rootFields := make([]string, 0, len(groups))
	for _, repository := range groups {
		first := -1
		for index := range targets {
			if targets[index].Repository == repository {
				first = index
				break
			}
		}
		ref, _ := pullRequestReferenceFromURL(targets[first].Task.PRURL)
		rootFields = append(rootFields, fmt.Sprintf(`%s: repository(owner: %s, name: %s) {
%s
}`, repository, strconv.Quote(ref.Owner), strconv.Quote(ref.Repo), strings.Join(groupFields[repository], "\n")))
	}
	return "query {\n" + strings.Join(rootFields, "\n") + "\n}", targets
}

func (response *ghQueryResponse) pullRequest(target prWatchTarget) (*ghPullRequest, error) {
	data, ok := response.Data.Repositories[target.Repository]
	if !ok || len(data) == 0 || string(data) == "null" {
		return nil, fmt.Errorf("GraphQL response omitted repository alias %s", target.Repository)
	}
	var repository map[string]*ghPullRequest
	if err := json.Unmarshal(data, &repository); err != nil {
		return nil, fmt.Errorf("invalid GraphQL repository alias %s: %w", target.Repository, err)
	}
	pull := repository[target.Pull]
	if pull == nil {
		return nil, fmt.Errorf("GraphQL response omitted pull request %s", target.Task.PRURL)
	}
	return pull, nil
}

