package store

import (
	"context"
	"encoding/json"
	"time"
)

// RecordVerifiedPRHead retains a head that was checked against the Task's
// branch and forge before a later follow-up clears the recorded merge head.
func (db *DB) RecordVerifiedPRHead(ctx context.Context, taskID int64, url, sha string) error {
	_, err := db.ExecContext(ctx, `INSERT OR IGNORE INTO verified_pr_heads(task_id, pr_url, head_sha) VALUES (?,?,?)`, taskID, url, sha)
	return err
}

// CreatePROpenedNoticeOnce records one opened Notice for each observed PR head.
func (db *DB) CreatePROpenedNoticeOnce(ctx context.Context, projectID, taskID int64, summary, url, sha string) (bool, error) {
	dataJSON, err := json.Marshal(struct {
		URL     string `json:"url"`
		HeadSHA string `json:"head_sha"`
	}{URL: url, HeadSHA: sha})
	if err != nil {
		return false, err
	}
	result, err := db.ExecContext(ctx, `INSERT INTO notices(project_id, task_id, kind, summary, data_json, created_at)
		SELECT ?, ?, 'pr_opened', ?, ?, ?
		WHERE NOT EXISTS (
			SELECT 1 FROM notices
			WHERE project_id=? AND task_id=? AND kind='pr_opened' AND json_valid(data_json)
			AND json_extract(data_json, '$.url')=? AND json_extract(data_json, '$.head_sha')=?
		)`, projectID, taskID, summary, string(dataJSON), time.Now().UnixMilli(), projectID, taskID, url, sha)
	if err != nil {
		return false, err
	}
	rows, err := result.RowsAffected()
	if err != nil || rows == 0 {
		return rows > 0, err
	}
	return true, db.PersistProject(ctx, projectID)
}

func (db *DB) WasVerifiedPRHead(ctx context.Context, taskID int64, url, sha string) (bool, error) {
	var found bool
	err := db.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM verified_pr_heads WHERE task_id=? AND pr_url=? AND head_sha=?)`, taskID, url, sha).Scan(&found)
	if err != nil || found {
		return found, err
	}
	// PRs opened before verified_pr_heads existed still have the head and URL
	// recorded in their pr_opened Notice from the validated publication head.
	rows, err := db.QueryContext(ctx, `SELECT data_json FROM notices WHERE task_id=? AND kind='pr_opened'`, taskID)
	if err != nil {
		return false, err
	}
	defer rows.Close()
	for rows.Next() {
		var data string
		if err := rows.Scan(&data); err != nil {
			return false, err
		}
		var opened struct {
			URL  string `json:"url"`
			Head string `json:"head_sha"`
		}
		if json.Unmarshal([]byte(data), &opened) == nil && opened.URL == url && opened.Head == sha {
			return true, nil
		}
	}
	return false, rows.Err()
}

// WasVerifiedTaskHead reports whether sha was verified as the head of any of
// the Task's pull requests.
func (db *DB) WasVerifiedTaskHead(ctx context.Context, taskID int64, sha string) (bool, error) {
	var found bool
	err := db.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM verified_pr_heads WHERE task_id=? AND head_sha=?)`, taskID, sha).Scan(&found)
	return found, err
}

// CreateSpecReadyNoticeOnce raises the spec_ready_to_deliver Notice for a spec
// unless one already exists for it.
func (db *DB) CreateSpecReadyNoticeOnce(ctx context.Context, projectID, taskID int64, spec int, summary string) (bool, error) {
	dataJSON, err := json.Marshal(map[string]int{"spec": spec})
	if err != nil {
		return false, err
	}
	result, err := db.ExecContext(ctx, `INSERT INTO notices(project_id, task_id, kind, summary, data_json, created_at)
		SELECT ?, ?, 'spec_ready_to_deliver', ?, ?, ?
		WHERE NOT EXISTS (
			SELECT 1 FROM notices
			WHERE project_id=? AND kind='spec_ready_to_deliver' AND json_valid(data_json)
			AND json_extract(data_json, '$.spec')=?
		)`, projectID, taskID, summary, string(dataJSON), time.Now().UnixMilli(), projectID, spec)
	if err != nil {
		return false, err
	}
	rows, err := result.RowsAffected()
	if err != nil || rows == 0 {
		return rows > 0, err
	}
	return true, db.PersistProject(ctx, projectID)
}

