52: 	gitTest(t, f.env, task.WorktreePath, "fetch", "origin", target+":refs/remotes/origin/"+target)
53: 	f.writeGraphQL(t, "pr1", "MERGED", "SUCCESS", "APPROVED", "MERGEABLE", mergedHead, task.GatedSHA)
54: 	if err := f.db.Transition(context.Background(), task.ID, store.StateMerging, store.StateDone, "cli", "external merge observation delayed"); err != nil {
55: 		t.Fatal(err)
56: 	}
57: 	command := exec.Command(f.binary, "teardown", "t1")
58: 	command.Dir, command.Env = f.repo, f.leadEnv
59: 	output, err := command.CombinedOutput()
60: 	if err != nil {
61: 		t.Fatalf("teardown could not settle the externally merged Task: %v\n%s", err, output)
62: 	}
63: 	mergeOutput := runPosse(t, f.binary, f.repo, f.leadEnv, "merge", "t1")
64: 	if !strings.Contains(mergeOutput, "already merged") {
65: 		t.Fatalf("merge disagreed with the settled PR: %s", mergeOutput)
66: 	}
67: 	discard := exec.Command(f.binary, "teardown", "t1", "--discard", "--user-approved", "User approved discarding this Task")
68: 	discard.Dir, discard.Env = f.repo, f.leadEnv
69: 	if output, err := discard.CombinedOutput(); err != nil {
70: 		t.Fatalf("discard disagreed with the settled Task state: %v\n%s", err, output)
71: 	}
72: 	settled := f.mustTask(t, "t1")
73: 	if settled.State != store.StateMerged && settled.State != store.StateTornDown {
74: 		t.Fatalf("externally merged PR did not settle on the next poll: state=%s", settled.State)
75: 	}
76: 	if settled.MergedRef != mergedHead {
77: 		t.Fatalf("merged ref = %s, want published merge head %s", settled.MergedRef, mergedHead)
78: 	}
79: 	f.requireNotice(t, "t1", "pr_merged")
80: }
